"""Measured, scoped evaluation. Gold annotations are separately authored fixture expectations."""
import json,html,importlib.metadata,platform,tempfile
from pathlib import Path
from .store import ROOT,Store,now,digest
from .services import Service
from .analysis import validate_evidence
from .models import SourceDocument,Extraction
from .detection import fixture_test

def evaluate():
    gold=json.loads((ROOT/'fixtures/gold.json').read_text());results=[];total_tp=total_fp=total_fn=0
    with tempfile.TemporaryDirectory(prefix='iti-eval-') as tmp:
        service=Service(Store(Path(tmp)))
        for name,expected in gold['fixtures'].items():
            j=service.submit('fictional-bank','windows-ad',expected['mode'],'case',name,background=False)
            if j['state']!='complete':results.append({'fixture':name,'status':'failed','error':j['data'].get('error')});continue
            a=service.store.get('assessment',j['data']['assessment_id']);p=service.generate(a['id'],'fictional-bank')
            got={b['key'] for b in a['extraction']['behaviors']};want=set(expected['behaviors']);tp=len(got&want);fp=len(got-want);fn=len(want-got);total_tp+=tp;total_fp+=fp;total_fn+=fn
            indicators={o['value'] for o in a['extraction']['observables'] if o['maliciousness_asserted']};wanted_indicators=set(expected['malicious_indicators'])
            evidence=validate_evidence(Extraction.model_validate(a['extraction']),SourceDocument.model_validate(a['source']))
            results.append({'fixture':name,'held_out':expected['held_out'],'mode':a['extraction']['mode'],'status':'completed','behaviors':{'expected':sorted(want),'actual':sorted(got),'true_positive':tp,'false_positive':fp,'false_negative':fn,'precision':tp/(tp+fp) if tp+fp else None,'recall':tp/(tp+fn) if tp+fn else None},'indicators':{'expected':sorted(wanted_indicators),'actual':sorted(indicators),'false_assertions':sorted(indicators-wanted_indicators),'missed':sorted(wanted_indicators-indicators)},'evidence_references_valid':evidence,'attribution_checks':{'confirmed_actor_assertions':sum('confirmed actor' in b['text'].lower() and 'not confirmed' not in b['text'].lower() for b in a['extraction']['behaviors']),'qualifiers_retained':[c['qualifier'] for c in a['extraction']['claims']]},'abstained_from_plans':not p['hunts'] and not p['emulations'],'expected_omissions':expected['expected_omissions'],'schema_results':p['artifacts']['validation'],'retrieval':{'searched_rules':a['retrieval']['searched_rules'],'source_cited_found':a['retrieval']['source_cited_found'],'source_cited_missing':a['retrieval']['source_cited_missing'],'independent_candidates':sum(c['retrieval']!='source-cited' for c in a['candidates'])},'source_completeness':a['source']['completeness']})
    report={'schema_version':'1.0','executed_at':now(),'fixture_count':len(results),'gold_labeler':gold['labeler'],'gold_hash':digest((ROOT/'fixtures/gold.json').read_bytes()),'labeled_behavior_subset':{'tp':total_tp,'fp':total_fp,'fn':total_fn,'precision':total_tp/(total_tp+total_fp) if total_tp+total_fp else None,'recall':total_tp/(total_tp+total_fn) if total_tp+total_fn else None},'fixtures':results,'synthetic_detection':fixture_test('19b08b1c-861d-4e75-a1ef-ea0c1baf202b'),'live_model_evaluation':{'status':'NOT VERIFIED','reason':'No successful configured live-provider acceptance run recorded; deterministic results are not model accuracy'},'limitations':['Four small authored/limited-derived fixtures only; not representative detection or CTI accuracy','Replay recovery is not new inference','Gold labels developer/model-curated, not independently human-reviewed','Exact span references and quotes cannot establish semantic truth','Source-cited rule retrieval is not independent discovery ability','Restricted matcher supports a small stateless subset, not all Sigma or a SIEM','No live Gmail handoff, live MISP instance, live Splunk or prevention/SOC exercise claimed'],'versions':{name:importlib.metadata.version(name) for name in ['fastapi','pydantic','stix2','stix2-validator','pymisp','misp-stix','pysigma','pysigma-backend-splunk','openai','pypdf','pytest']}|{'python':platform.python_version(),'platform':platform.platform()}}
    out=ROOT/'validation';out.mkdir(exist_ok=True);(out/'evaluation.json').write_text(json.dumps(report,indent=2))
    rows=''.join(f'<tr><td>{r["fixture"]}</td><td>{r.get("mode")}</td><td>{r.get("held_out")}</td><td>{r.get("behaviors",{}).get("true_positive")}</td><td>{r.get("behaviors",{}).get("false_positive")}</td><td>{r.get("behaviors",{}).get("false_negative")}</td><td>{r.get("source_completeness")}</td></tr>' for r in results)
    document=f'<!doctype html><html lang="en"><meta charset="utf-8"><title>Intel to Improvements — actual evaluation</title><style>body{{font:15px system-ui;max-width:1100px;margin:50px auto;color:#23433b;background:#f6faf7}}table{{border-collapse:collapse;width:100%;background:white}}td,th{{text-align:left;padding:12px;border:1px solid #cddbce}}pre{{white-space:pre-wrap;font-size:11px;background:white;padding:20px}}h1{{font-size:30px}}</style><h1>Intel to Improvements · evaluation</h1><p>Executed {report["executed_at"]}. {html.escape(gold["labeler"])}</p><p>Labeled behavior subset precision {report["labeled_behavior_subset"]["precision"]}; recall {report["labeled_behavior_subset"]["recall"]}. Scope limits below apply.</p><table><tr><th>Fixture</th><th>Mode</th><th>Held out</th><th>TP</th><th>FP</th><th>FN</th><th>Completeness</th></tr>{rows}</table><h2>Limitations and complete measured output</h2><pre>{html.escape(json.dumps(report,indent=2))}</pre></html>'
    (out/'evaluation.html').write_text(document)
    return report
